mapper.select:
		SELECT
			A.start_date, A.end_date, A.AGENCY_NAME, A.APPLY_IDX, A.MEDIAFACTORY_IDX, B.DATE_TYPE,
			(SELECT CODE_NAME FROM CMS_CODE C WHERE B.homepage_id = C.homepage_id AND C.CODE_ID = B.DATE_TYPE AND C.GROUP_ID = 'H0001') AS CODE_NAME,
			A.APPLICANT_MEMBER_ID
		FROM
			CMS_MEDIAFACTORY_APPLY A, CMS_MEDIAFACTORY B
		WHERE
			A.MEDIAFACTORY_IDX = B.MEDIAFACTORY_IDX
		AND	A.homepage_id = B.homepage_id
		AND	A.homepage_id = #{homepage_id}
		AND	A.APPLY_STATE = '3'

 		AND (
 				substr(A.start_date,1,7) = #{plan_date}
			OR	substr(A.end_date,1,7) = #{plan_date}
			)


 		AND (
 				A.start_date = #{plan_day}
			OR	A.end_date = #{plan_day}
			)
